#[test]
fn test_validate_transaction() {
    let tx_hex = "";
    let utxo_1: UTxO = serde_json::from_str("{\"input\":{\"outputIndex\":1,\"txHash\":\"6153c1e9a628fc2bc1ebc82d1f6b6d360c3f5a895171cfd8a792541ab51f7509\"},\"output\":{\"address\":\"addr1q80y4whnp6y5ajfy8w9mj7khg9936vyxsvad30cj6yqnp5r2vrs4j05rcf6n6w8wvxpar47dkzsutjax2lre3zz3y2nqh3h7xa\",\"amount\":[{\"unit\":\"lovelace\",\"quantity\":\"1784340\"},{\"unit\":\"6ac8ef33b510ec004fe11585f7c5a9f0c07f0c23428ab4f29c1d7d104d454c44\",\"quantity\":\"5000000\"},{\"unit\":\"a0028f350aaabe0545fdcb56b039bfb08e4bb4d8c4d7c3c7d481c235484f534b59\",\"quantity\":\"20250010\"},{\"unit\":\"a2944573e99d2ed3055b808eaa264f0bf119e01fc6b18863067c63e44d454c44\",\"quantity\":\"15015000994000\"},{\"unit\":\"b06729158210bf1ba13f8f3d7d422a918d3eaa82561a705552a2568b4d656c642042616e6b204d616e616765722076312033393937\",\"quantity\":\"1\"}]}}").unwrap();
    let utxo_2: UTxO = serde_json::from_str("{\"input\":{\"outputIndex\":2,\"txHash\":\"6153c1e9a628fc2bc1ebc82d1f6b6d360c3f5a895171cfd8a792541ab51f7509\"},\"output\":{\"address\":\"addr1q80y4whnp6y5ajfy8w9mj7khg9936vyxsvad30cj6yqnp5r2vrs4j05rcf6n6w8wvxpar47dkzsutjax2lre3zz3y2nqh3h7xa\",\"amount\":[{\"unit\":\"lovelace\",\"quantity\":\"445509838\"}]}}").unwrap();
    let utxo_3: UTxO = serde_json::from_str("{\"input\":{\"outputIndex\":0,\"txHash\":\"cb78d0612a8a54e4cbe43c90e23dc7739f0b27fffbd7caa5368d9b98047601b1\"},\"output\":{\"address\":\"addr1wyvvjx7l749d3axnvxyp3umtn8jqrj48a2c48dp02yc3evqzypx02\",\"amount\":[{\"unit\":\"lovelace\",\"quantity\":\"2267060\"},{\"unit\":\"4d564c6e31f771d71471437ea9f0e60038be09619755f8720eb093cd\",\"quantity\":\"1\"},{\"unit\":\"9e3ca7a4d3ae25b02b1ce833b8d85bd8a6a8fda186a93a0bc504d454\",\"quantity\":\"1\"},{\"unit\":\"d30ee8c513b3fabada55d802a5ca5bb12e43b42027017309ed71ed4b\",\"quantity\":\"1\"}],\"dataHash\":\"671a25e519487eeb4a3ec3abf857d5f0f561edae50386966e456572541ac7451\",\"plutusData\":\"d8799f1b00002d79cfe23080ff\",\"scriptRef\":\"\",\"scriptHash\":\"4d564c6e31f771d71471437ea9f0e60038be09619755f8720eb093cd\"}}").unwrap();
    let utxo_4: UTxO = serde_json::from_str("{\"input\":{\"outputIndex\":1,\"txHash\":\"125192e26ab0fedcfb32d54176d4cffdbde39b22f68d13f64c85bc7d64bd71a5\"},\"output\":{\"address\":\"addr1wypan0u8f2jsewz97nw0qydzy0k5k8xd2x6gtxgt4fuavastxq94l\",\"amount\":[{\"unit\":\"lovelace\",\"quantity\":\"6646020\"}],\"scriptRef\":\"\",\"scriptHash\":\"18c91bdff54ad8f4d3618818f36b99e401caa7eab153b42f51311cb0\"}}").unwrap();
    let utxo_5: UTxO = serde_json::from_str("{\"input\":{\"outputIndex\":3,\"txHash\":\"125192e26ab0fedcfb32d54176d4cffdbde39b22f68d13f64c85bc7d64bd71a5\"},\"output\":{\"address\":\"addr1wypan0u8f2jsewz97nw0qydzy0k5k8xd2x6gtxgt4fuavastxq94l\",\"amount\":[{\"unit\":\"lovelace\",\"quantity\":\"7779550\"}],\"scriptRef\":\"\",\"scriptHash\":\"a2944573e99d2ed3055b808eaa264f0bf119e01fc6b18863067c63e4\"}}").unwrap();
    let utxo_context_1 = UtxoInputContext {
        utxo: utxo_1,
    is_spent: false,
    };
    let utxo_context_2 = UtxoInputContext {
        utxo: utxo_2,
        is_spent: false,
    };
    let utxo_context_3 = UtxoInputContext {
        utxo: utxo_3,
        is_spent: false,
    };
    let utxo_context_4 = UtxoInputContext {
        utxo: utxo_4,
        is_spent: false,
    };
    let utxo_context_5 = UtxoInputContext {
        utxo: utxo_5,
        is_spent: false,
    };
    let validation_context = ValidationInputContext::new(
        vec![
            utxo_context_1,
            utxo_context_2,
            utxo_context_3,
            utxo_context_4,
            utxo_context_5,
        ],
        get_test_protocol_parameters(),
        104895074,
        vec![],
        vec![],
        vec![],
        vec![],
        vec![],
        0,
        NetworkType::Mainnet,
        vec![],
        vec![],
    );
    let validation_result = validate_transaction(tx_hex, validation_context);
    assert!(validation_result.is_ok(), "Transaction validation failed: {:?}", validation_result.err());
    let validation_result = validation_result.unwrap();
    for error in &validation_result.errors {
        println!("{:?}", error);
    }
    for warning in &validation_result.warnings {
        println!("{:?}", warning);
    }

    // Phase 2 must have evaluated both plutus redeemers carried by this tx.
    assert!(
        validation_result.phase2_errors.is_empty(),
        "unexpected phase 2 errors: {:?}",
        validation_result.phase2_errors
    );
    let evals = &validation_result.eval_redeemer_results;
    assert_eq!(
        evals.len(),
        2,
        "expected 2 redeemer evaluations, got {}: {:?}",
        evals.len(),
        evals
    );
    for eval in evals {
        assert!(
            eval.success && eval.error.is_none(),
            "redeemer {:?}#{} did not evaluate successfully: {:?}",
            eval.tag,
            eval.index,
            eval.error
        );
        assert!(
            eval.calculated_ex_units.mem > 0 && eval.calculated_ex_units.steps > 0,
            "redeemer {:?}#{} reported zero ex units: {:?}",
            eval.tag,
            eval.index,
            eval.calculated_ex_units
        );
        assert!(
            eval.script_context_bytes.is_some(),
            "redeemer {:?}#{} is missing script_context_bytes",
            eval.tag,
            eval.index
        );
        // The mapped script context must be present and valid JSON.
        let ctx_json = eval.script_context.as_ref().unwrap_or_else(|| {
            panic!("redeemer {:?}#{} is missing script_context", eval.tag, eval.index)
        });
        serde_json::from_str::<serde_json::Value>(ctx_json).unwrap_or_else(|e| {
            panic!(
                "redeemer {:?}#{} script_context is not valid JSON: {}",
                eval.tag, eval.index, e
            )
        });
    }
}


